UPDATE dynasties SET note = '魏（220年12月11日－266年2月4日，史称曹魏、大魏、魏朝或魏國）共歷五帝，國祚約46年。是中國歷史上三國時期位于北方的政權，始於213年曹操受封为魏公，建国于220年魏王曹丕受漢獻帝禪讓，代漢為魏，249年司马懿发动高平陵之变成功后，其家族成为曹魏实际掌权者，至266……。' WHERE id = 'wei';
UPDATE dynasties SET note = '缩略图|300px|右 赵国，戰國七雄之一的諸侯國，也作勺国，初都晋阳（今山西太原），后迁都中牟（今河南鹤壁），又迁至邯郸（今河北省邯郸），疆土主要有当今河北省南部、山西省中部和陕西省东北隅。西有秦国，南有魏国、韩国，东有齐国，东北燕国，北方则是林胡、楼烦、东胡等游牧民族的地……。' WHERE id = 'zhao-warring';
UPDATE persons SET bio = '，（）即阿柴，南北朝时期政治人物。他為4－6世紀建立之吐谷渾第九任統治者，武王樹洛干弟弟，承襲树洛干擔任首領，在位期間為417年-426年，谥号威王。' WHERE id = 'achen';
UPDATE persons SET bio = '，原为胡特勤，跌氏，是回鹘汗国的第十二任可汗，昭禮可汗的侄子。832年，昭禮可汗被部下所杀，胡特勤继立为爱登里啰汩没蜜施合句录毗伽可汗（爱登里罗汨没施合句禄毗伽可汗）。' WHERE id = 'aidengli-kehan';
UPDATE persons SET bio = 'left|thumb|200px|三国史记中的高句丽世系 安藏王（），高句丽第22代君主。文咨王之子，名兴安，中國史籍稱之為「高安」，公元518-531在位。' WHERE id = 'ancang-wang';
