UPDATE persons SET bio = '-{蚡冒}-（），一作鼢冒，芈姓，熊氏，名眴，东周初期的楚国君主，《韩非子》和《楚辞·东方朔·七谏》作楚厲王，芈姓，熊氏，是西周时期楚国的一位国君。楚霄敖長子，在位始启濮，“開濮地而有之”，向濮人之地拓土，征服陉隰。' WHERE id = 'chu-r15';
