UPDATE persons SET bio = '，原名启瑞，字芝泉，安徽合肥人，祖籍江西饒州，中國政治人物，历任中華民國參謀總長、國務卿、國務總理、臨時執政。在任期間，反對帝制、總統制，再造共和，提倡責任內閣制，主張武力統一中國，在第一次世界大战中带领中国成为战胜国，加入國際聯盟，并迫使外蒙古撤治。' WHERE id = 'duan-qirui';
